using System;
using System.Collections.Immutable;
using System.Linq;
using Extensions.Pack;
using AspNetCore.MinimalApi.Sdk.CodeRules.Api.Controllers;
using Solution.Parser.CSharp;

namespace AspNetCore.MinimalApi.Sdk.CodeRules
{
    [TestCategory("Coding-Rules")]
    [TestCategory("API - Minimal API")]
    [TestClass]
    public class RJIT_CR_MAPI_00006 : MinimalApiTestBase
    {
        [TestMethod]
        public void Each_Minimal_Api_Should_Produce_At_Least_One_Bad_Request_Status_Code()
        {
            var missingProduces = (from mapStatement in MapStatements
                                   where mapStatement.SyntaxTree.DoesNotContain(".Produces(4")
                                   select new
                                   {
                                       Error = $@"
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
FilePath:  {mapStatement.FilePath}
-----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Syntax:    

{mapStatement.SyntaxTree.FormatSyntaxTree()}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Sample:

{mapStatement.SyntaxTree.Replace("});", "}).Produces(400, typeof(ProblemDetails));").FormatSyntaxTree()}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
"
                                   }).ToImmutableList();

            Assert.IsTrue(missingProduces.IsEmpty(),
                @$"
Documentation: {DocumentationDomain}#RJIT_CR_MAPI_00006

Please use at least one '.Produces(4xx, typeof(ProblemDetails))' to provide the correct bad request status code and your real response object.

Findings {missingProduces.Count}': 

{missingProduces.Select(error => error.Error).Flatten(Environment.NewLine)}{Environment.NewLine}");
        }
    }


